#include <stdio.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int G[100][100];

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            scanf("%d", &G[i][j]);
        }
    }

    int cost0 = 0, cost1 = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int gp = G[i][j] & 1;
            int par = (i + j) & 1;

            if (gp != par) {
                cost0++;
            } else {
                cost1++;
            }
        }
    }

    int best = (cost0 <= cost1) ? 0 : 1;
    int answer = (best == 0) ? cost0 : cost1;

    printf("%d\n", answer);

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            int gp = G[i][j] & 1;
            int par = (i + j) & 1;
            int target = (best == 0) ? par : (1 - par);

            int val = G[i][j] + (gp != target ? 1 : 0);

            printf("%d", val);
            if (j + 1 < M) printf(" ");
        }
        printf("\n");
    }

    return 0;
}
